export const DE_DESEN: [RegExp, (m: RegExpExecArray, t: (s: string) => string) => string][] = [
  [/^Sulanmayan (.+) için temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `Grundbedarf an Stickstoff für ${t(b(m[1]))} ohne Bewässerung: ${m[2]} kg/da.`; }], /* tahil */
  [/^(\d+) su verilen (.+) daha yüksek verim verir; temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `${t(b(m[2]))} mit ${m[1]} Bewässerungen bringt mehr Ertrag; Grundbedarf an Stickstoff ${m[3]} kg/da.`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak kendiliğinden az azot verir, azot hedefi ([\d.,]+) kg\/da artırıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Organische Substanz ${m[1]} % (${({"çok az": "sehr niedrig", "az": "niedrig", "orta": "mittel", "iyi": "gut", "yüksek": "hoch", "çok yüksek": "sehr hoch", "yeterli": "ausreichend"} as Record<string, string>)[m[2]] ?? m[2]}): Der Boden liefert selbst wenig Stickstoff, das Stickstoffziel wurde um ${m[3]} kg/da erhöht (gesamt ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak azotun bir kısmını kendisi verir, azot hedefi ([\d.,]+) kg\/da azaltıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Organische Substanz ${m[1]} % (${({"çok az": "sehr niedrig", "az": "niedrig", "orta": "mittel", "iyi": "gut", "yüksek": "hoch", "çok yüksek": "sehr hoch", "yeterli": "ausreichend"} as Record<string, string>)[m[2]] ?? m[2]}): Der Boden liefert einen Teil des Stickstoffs selbst, das Stickstoffziel wurde um ${m[3]} kg/da gesenkt (gesamt ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \(orta\): azot hedefi değiştirilmedi \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Organische Substanz ${m[1]} % (mittel): Stickstoffziel unverändert (gesamt ${m[2]} kg/da).`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): ekimde ([\d.,]+) kg\/da saf fosfor \(P₂O₅\) verilir\.$/, (m) => { return `Phosphor ${m[1]} kg/da (${({"çok az": "sehr niedrig", "az": "niedrig", "orta": "mittel", "iyi": "gut", "yüksek": "hoch", "çok yüksek": "sehr hoch", "yeterli": "ausreichend"} as Record<string, string>)[m[2]] ?? m[2]}): Zur Saat werden ${m[3]} kg/da Reinphosphor (P₂O₅) gegeben.`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): fosforlu gübreye gerek yok\.$/, (m) => { return `Phosphor ${m[1]} kg/da (${({"çok az": "sehr niedrig", "az": "niedrig", "orta": "mittel", "iyi": "gut", "yüksek": "hoch", "çok yüksek": "sehr hoch", "yeterli": "ausreichend"} as Record<string, string>)[m[2]] ?? m[2]}): kein Phosphatdünger nötig.`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): ([\d.,]+) kg\/da saf potasyum \(K₂O\) eklendi\.$/, (m) => { return `Kalium ${m[1]} kg/da (${({"çok az": "sehr niedrig", "az": "niedrig", "orta": "mittel", "iyi": "gut", "yüksek": "hoch", "çok yüksek": "sehr hoch", "yeterli": "ausreichend"} as Record<string, string>)[m[2]] ?? m[2]}): ${m[3]} kg/da Reinkalium (K₂O) ergänzt.`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): potasyumlu gübreye gerek yok\.$/, (m) => { return `Kalium ${m[1]} kg/da (${({"çok az": "sehr niedrig", "az": "niedrig", "orta": "mittel", "iyi": "gut", "yüksek": "hoch", "çok yüksek": "sehr hoch", "yeterli": "ausreichend"} as Record<string, string>)[m[2]] ?? m[2]}): kein Kalidünger nötig.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(düşük\): taban gübresi çinkolu seçildi, yapraktan çinko önemli\.$/, (m) => { return `Zink ${m[1]} mg/kg (niedrig): zinkhaltiger Grunddünger gewählt, Blattdüngung mit Zink ist wichtig.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(yeterli\)\.$/, (m) => { return `Zink ${m[1]} mg/kg (ausreichend).`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(düşük\): kanola bora çok ihtiyaç duyar; tomurcuk ve çiçeklenmedeki yapraktan bor \(MICROSENSE Ca & B\) uygulamalarını atlamayın\.$/, (m) => { return `Bor ${m[1]} mg/kg (niedrig): Raps braucht viel Bor; die Bor-Blattdüngung (MICROSENSE Ca & B) zu Knospe und Blüte nicht auslassen.`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(yeterli\); yapraktan bor yine de çiçek tutumunu destekler\.$/, (m) => { return `Bor ${m[1]} mg/kg (ausreichend); Bor über das Blatt fördert trotzdem den Schotenansatz.`; }], /* tahil */
  [/^Kanola kükürde çok ihtiyaç duyar \(yaklaşık 4 kg\/da\); plandaki gübreler ≈ ([\d.,]+) kg\/da veriyor, kapsül döneminde yapraktan potasyum ve kükürt uygulamasını atlamayın\.$/, (m) => { return `Raps braucht viel Schwefel (etwa 4 kg/da); die Dünger im Plan liefern ≈ ${m[1]} kg/da, die Kalium- und Schwefel-Blattdüngung in der Schotenphase daher nicht auslassen.`; }], /* tahil */
  [/^Bezelye baklagildir; azotun çoğunu kökündeki bakterilerden alır\. Yalnızca ([\d.,]+) kg\/da başlangıç azotu verilir\.$/, (m) => { return `Erbsen sind Leguminosen und beziehen den größten Teil ihres Stickstoffs von den Knöllchenbakterien. Es werden nur ${m[1]} kg/da Startstickstoff gegeben.`; }], /* tahil */
  [/^Kireç %([\d.,]+): çinko ve fosfor alımı zorlaşır; fosfor çinkolu taban gübresiyle, azotun bir kısmı kükürtlü gübreyle \(ör\. amonyum sülfat\) verilir\.$/, (m) => `Kalk ${m[1]} %: Zink- und Phosphoraufnahme sind erschwert; Phosphor wird mit zinkhaltigem Grunddünger gegeben, ein Teil des Stickstoffs als schwefelhaltiger Dünger (z. B. Ammoniumsulfat).`],
  [/^en az (.+)$/, (m) => `mindestens ${m[1]}`],
  [/^en çok (.+)$/, (m) => `höchstens ${m[1]}`],
  [/^Bünye: (.+)$/, (m) => `Bodenart: ${m[1]}`],
  [/^(\d+) saat$/, (m) => `${m[1]} Std.`],
  [/^(.+) için bu değer olağan dışı görünüyor\.$/, (m) => `Dieser Wert erscheint für ${m[1]} ungewöhnlich.`],
  [/^Kum \+ silt \+ kil toplamı %(.+) çıktı; %100 olmalı\. Değerleri kontrol edin\.$/, (m) => `Sand + Schluff + Ton ergeben ${m[1]} %; es sollten 100 % sein. Bitte prüfen Sie die Werte.`],
  [/^(.+) bitkisinde (.+) noksanlığı$/, (m, t) => `${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1))}-Mangel bei ${t(m[1])}`],
  [/^(.+) bitkisinde (.+)$/, (m, t) => `${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1))} bei ${t(m[1])}`],
  [/^(.+) bitkisinde$/, (m, t) => `bei ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1))}`],
  [/^Azotlu gübre miktarını biraz azaltın; her 1\.000 m³ su ≈ (.+) kg azot getirir\.$/, (m) => `Die Stickstoffdüngung etwas reduzieren; je 1.000 m³ Wasser kommen ≈ ${m[1]} kg Stickstoff.`],
  [/^([A-Z][A-Za-z]{0,2}\d*) \((.+) Bünyeli\)$/, (m) => `${m[1]} (${m[2]})`],
  [/^([\d.,]+)( puan| [^\s(]+)? (eksik|fazla) \(%([\d.,]+)\)$/, (m) => `${m[1]}${m[2] === ' puan' ? ' Punkte' : m[2] ?? ''} ${m[3] === 'eksik' ? 'zu niedrig' : 'zu hoch'} (${m[4]} %)`],
  [/^(.+) noksanlığı$/, (m, t) => `${t(m[1])}-Mangel`],
  [/^(.+) bu tuzluluktan etkilenmez\.$/, (m, t) => `${t(m[1])} wird von diesem Salzgehalt nicht beeinträchtigt.`],
  [/^Bu tuzlulukta (.+) için beklenen verim yaklaşık %(\d+) \(tuzsuz suya göre\)\.$/, (m, t) => `Bei diesem Salzgehalt beträgt der erwartete Ertrag von ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1))} etwa ${m[2]} % (gegenüber salzfreiem Wasser).`],
  [/^(.+) tuza (.+)\.$/, (m, t) => `${t(m[1])} ist gegenüber Salz ${t(m[2])}.`],
  [/^(.+) bora (.+) \(sınır (.+)–(.+) mg\/l\)\.$/, (m, t) => `${t(m[1])} ist gegenüber Bor ${t(m[2])} (Grenze ${m[3]}–${m[4]} mg/l).`],
  [/^Toprağa ya da suya jips verin: .*\(sizde ≈ (.+) kg \/ 1\.000 m³\)\.$/, (m) => `Gips in Boden oder Wasser geben: je 1 me/l RSC etwa 86 kg Reingips auf 1.000 m³ Wasser (bei Ihnen ≈ ${m[1]} kg / 1.000 m³).`],
  [/^Bitkinin ihtiyacından yaklaşık %(\d+) fazla su verin \(yıkama suyu\); tuz kök bölgesinden uzaklaşır\.$/, (m) => `Geben Sie etwa ${m[1]} % mehr Wasser als der Bedarf der Pflanze (Auswaschungswasser); so wird das Salz aus dem Wurzelraum gespült.`],
  [/^Bu su için (.+) sulama daha uygun; imkânınız varsa geçmeyi düşünün\.$/, (m, t) => `Für dieses Wasser ist ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1))} besser geeignet; ziehen Sie einen Wechsel in Betracht, wenn möglich.`],
  [/^Sodyum ya da klorür yüksek \((.+) me\/l\): yaprak yanığı yapabilir; yalnızca akşam ve gece sulayın\.$/, (m) => `Natrium oder Chlorid hoch (${m[1]} me/l): kann Blattverbrennungen verursachen; nur abends und nachts bewässern.`],
];
